"use strict";
const test=require("node:test"),assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path");
const {fixture,commit,projection,bridge,scenarios,workspaceRef,request}=require("./oath-committed-fixture.cjs");
const baseline=require("./oath-committed-baseline.json");
for(const[name,change]of Object.entries(scenarios))test("facade matches frozen original resolution/source/metadata/commitment: "+name,async()=>{
 const f=fixture();try{commit(f);change(f);await f.oath.resolveWork();const old=baseline.find(b=>b.name===name);assert.deepEqual(projection(f.oath.work),old.work);assert.deepEqual(f.snapshot(),old.snapshot);assert.deepEqual(f.oath.current,old.current);assert.deepEqual([...f.oath.awaitingIndex.keys()],old.pending);assert.equal(f.state.writes,0);}finally{await f.close();}
});
for(const id of["private","itacan","hub","future-project","shelved","resource:study","resource:literature","resource:references","resource:inspiration"])
test("actual original/current committed workspace policy: "+id,async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{const owner=f.owners.find(o=>o.projectId===id);if(id==="shelved")f.add(owner.root+"/Tasks.md","- [ ] Shelved task <!-- hub-task:shelved-task -->\n");const task=f.oath.tasks().find(t=>t.path.startsWith(owner.root+"/")&&!t.identityConflict&&t.hubTaskId);commit(f,[task.hubTaskId],workspaceRef(owner));await f.oath.resolveWork();assert(f.oath.work[0].task);results.push(projection(f.oath.work));}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
for(const options of[{},{preexisting:true},{preexisting:true,indexed:true}])test("unchanged enrollment, display, delayed bridge, canonical import and outcome "+JSON.stringify(options),async()=>{
 const results=[];for(const original of[true,false]){const f=fixture({original});try{const b=await bridge(f,options),immediate=structuredClone(f.oath.work),pending=structuredClone([...f.oath.awaitingIndex]);await f.oath.resolveWork();const resolved=projection(f.oath.work);assert(resolved[0].task);b.import();await f.oath.resolveWork();assert.equal(f.oath.awaitingIndex.size,0);results.push({immediate,pending,resolved,canonical:projection(f.oath.work),snapshot:f.snapshot(),saved:f.saved,current:f.oath.current});}finally{await f.close();}}assert.deepEqual(results[1],results[0]);
});
for(const fault of["source-save","commitment-save"])test("original enrollment failure semantics unchanged: "+fault,async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{f.state.failWrite=fault==="source-save";f.failPersist(fault==="commitment-save");let error;try{await bridge(f);}catch(e){error=e.message;}assert(error);results.push({error,snapshot:f.snapshot(),saved:f.saved,current:f.oath.current,pending:[...f.oath.awaitingIndex]});}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
for(const change of["copy","source-id","delete","owner","text","move","wrong-import"])
test("temporary enrollment evidence cannot bypass validation: "+change,async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{const b=await bridge(f,{preexisting:true});if(change==="copy")f.add("Outside/Copy.md",`- [ ] Copy <!-- hub-task:${b.id} -->\n- [ ] Other copy <!-- hub-task:${b.id} -->\n`);if(change==="source-id")f.contents.set(b.note,"- [ ] Bridge <!-- hub-task:other -->\n");if(change==="delete")f.remove(f.files.get(b.note));if(change==="owner")f.owners[0].root="Projects/Elsewhere";if(change==="text")f.contents.set(b.note,f.contents.get(b.note).replace("Bridge","Changed"));if(change==="move")f.move(f.files.get(b.note),"Projects/Private/Moved-Bridge.md");if(change==="wrong-import")f.add("Resources/Knowledge/Wrong.md",`- [ ] Wrong <!-- hub-task:${b.id} -->\n`);await f.oath.resolveWork();results.push(projection(f.oath.work));if(["copy","source-id","delete","owner","wrong-import"].includes(change))assert.equal(f.oath.work[0].task,null);}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
test("pending ID copied onto an indexed Step fails closed",async()=>{const f=fixture();try{const b=await bridge(f);f.add("Outside/Step.md",`- [ ] Other\n    - [ ] Copy <!-- hub-task:${b.id} -->\n`);await f.oath.resolveWork();assert.equal(f.oath.work[0].task,null);assert(f.oath.readDiagnostics.some(d=>d.code==="AMBIGUOUS_REFERENCE"));}finally{await f.close();}});
test("missing and failed reads retain commitment identity/order and recover",async()=>{const f=fixture();try{const refs=commit(f,["parent","absent","complete"]);await f.oath.resolveWork();assert.deepEqual(f.oath.work.map(i=>i.ref),refs);const work=f.oath.work,read=f.adapter.resolveOathWork.bind(f.adapter);f.adapter.resolveOathWork=async()=>{throw Error("Temporary facade failure");};await assert.rejects(f.oath.resolveWork(),/Temporary/);assert.equal(f.oath.work,work);assert.equal(f.oath.current.fulfilledAt,null);f.adapter.resolveOathWork=read;await f.oath.resolveWork();assert.equal(f.oath.work[1].task,null);assert(f.oath.work[0].task);assert.deepEqual(f.oath.current.tasks,refs);}finally{await f.close();}});
test("source read error is explicit unavailable evidence, then recovers",async()=>{const f=fixture();try{commit(f);const read=f.vault.read;f.vault.read=async()=>{throw Error("Temporary source failure");};await f.oath.resolveWork();assert.equal(f.oath.work[0].task,null);assert(f.oath.readDiagnostics.some(d=>d.code==="SOURCE_VALIDATION_FAILED"));f.vault.read=read;await f.oath.resolveWork();assert(f.oath.work[0].task);}finally{await f.close();}});
test("global copies appearing and disappearing are rechecked",async()=>{const f=fixture();try{commit(f);await f.oath.resolveWork();assert(f.oath.work[0].task);const copy=f.add("Outside/New.md","- [ ] Copy <!-- hub-task:parent -->\n");await f.oath.resolveWork();assert.equal(f.oath.work[0].task,null);f.remove(copy);await f.oath.resolveWork();assert(f.oath.work[0].task);}finally{await f.close();}});
test("read-only portable contract, per-note batching, fresh rereads, no IDs/writes",async()=>{const f=fixture();try{commit(f,["parent","complete","steps-parent"]);const req=request(f),before=f.snapshot(),counts={...f.counts};const a=await f.service.resolveOathWork(req);assert.equal(f.counts.queries-counts.queries,1);assert.equal(f.counts.sources-counts.sources,1);assert.equal(a.rows.length,3);assert(a.rows.every(r=>r.task));assert(!JSON.stringify(a).includes('"block"'));assert(!JSON.stringify(a).includes('"children"'));assert.deepEqual(JSON.parse(JSON.stringify(a)),a);a.rows[0].task.text="Detached";const b=await f.service.resolveOathWork(req);assert.equal(f.counts.sources-counts.sources,2);assert.notEqual(b.rows[0].task.text,"Detached");assert.deepEqual(f.snapshot(),before);assert.equal(f.state.writes,0);assert.equal(f.counts.persists,0);assert.equal(f.service.capabilities().operations.resolveOathWork,true);for(const invalid of[{}, {workspace:req.workspace,references:[{path:"a",text:"x"}]},{...req,awaitingIndex:[{id:"parent",path:"x",line:-1,text:"x"}]}])await assert.rejects(f.service.resolveOathWork(invalid),e=>e.code==="VALIDATION");}finally{await f.close();}});
test("all protected Oath writers and methods outside read integration are byte-identical",()=>{require("./oath-committed-boundaries.cjs").unchangedOath(fs.readFileSync(path.join(__dirname,"oath-committed-original.cjs"),"utf8"),fs.readFileSync(path.join(__dirname,"../services/oath.js"),"utf8"));});
for(const source of["- [ ] Another parent\n    - [x] Parent <!-- hub-task:parent -->\n","```markdown\n- [x] Parent <!-- hub-task:parent -->\n```\n"])
test("fresh proof rejects a stale indexed parent now represented as a Step/code",async()=>{const f=fixture();try{commit(f);f.contents.set("Projects/Private/Tasks.md",source);await f.oath.resolveWork();assert.equal(f.oath.work[0].task,null);assert(f.oath.readDiagnostics.some(d=>d.code==="SOURCE_NOT_PARENT"));assert.equal(f.oath.current.fulfilledAt,null);}finally{await f.close();}});
test("source duplicate ID is explicitly ambiguous even before import",async()=>{const f=fixture();try{commit(f);const p="Projects/Private/Tasks.md";f.contents.set(p,f.contents.get(p)+"- [ ] Source copy <!-- hub-task:parent -->\n");await f.oath.resolveWork();assert.equal(f.oath.work[0].task,null);assert(f.oath.readDiagnostics.some(d=>d.code==="AMBIGUOUS_REFERENCE"));}finally{await f.close();}});
test("delayed bridge preserves original optional metadata overlay until import",async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{f.wizard.data.taskMetadata["source-existing"]={description:"Enrollment description",phaseId:"phase-1",dueDate:"2026-10-30",dueTime:"00:00",captureSource:{origin:"capture",title:"Original"}};await bridge(f,{preexisting:true});delete f.wizard.data.taskMetadata["source-existing"];await f.oath.resolveWork();assert.equal(f.oath.work[0].task.description,"Enrollment description");results.push(projection(f.oath.work));}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
test("arbitrary Dataview metadata is not enrollment overlay authority",async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{delete f.wizard.data.taskMetadata.parent.description;f.pages.get("Projects/Private/Tasks.md").file.tasks[0].metadata={description:"Unrelated index object"};commit(f);await f.oath.resolveWork();assert.equal(f.oath.work[0].task.description,undefined);results.push(projection(f.oath.work));}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
for(const change of["removed","reconfigured","renamed","missing-dashboard","to-project","mounted-project"])
test("original/current Resource registry/root/mount boundary: "+change,async()=>{const results=[];for(const original of[true,false]){const f=fixture({original});try{const owner=f.owners.find(o=>o.resourceType==="study"),source="Resources/Knowledge/Mounted/Tasks.md";commit(f,["resource-task"],change==="mounted-project"?{type:"project",id:"itacan"}:{type:"resource",id:"study"});if(change==="removed")f.owners.splice(f.owners.indexOf(owner),1);if(change==="reconfigured")owner.root="Resources/Reconfigured";if(change==="missing-dashboard")f.remove(f.files.get(owner.path));if(change==="to-project")f.move(f.files.get(source),"Projects/Private/Resource-Moved.md");if(change==="renamed"){f.move(f.files.get(owner.path),"Resources/Renamed/Renamed.md");owner.root="Resources/Renamed";owner.path="Resources/Renamed/Renamed.md";f.move(f.files.get(source),"Resources/Renamed/Mounted/Tasks.md");}if(change==="mounted-project")assert(f.oath.projectWorkspaceForPath(source));await f.oath.resolveWork();if(change==="renamed")assert(f.oath.work[0].task);else assert.equal(f.oath.work[0].task,null);results.push(projection(f.oath.work));}finally{await f.close();}}assert.deepEqual(results[1],results[0]);});
